// Extract links from email HTML body
// Works with both simplified and raw Gmail output
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Try multiple locations where HTML body might be
  let html = '';

  // 1. n8n Gmail Trigger with Simplify OFF — html is at top level
  if (data.html) {
    html = data.html;
  }
  // 2. Simplified format (simple: true)
  else if (data.textHtml) {
    html = data.textHtml;
  }
  // 3. Raw format - multipart (simple: false, older versions)
  else if (data.payload?.parts) {
    for (const part of data.payload.parts) {
      if (part.mimeType === 'text/html' && part.body?.data) {
        html = Buffer.from(part.body.data, 'base64url').toString('utf-8');
        break;
      }
      if (part.parts) {
        for (const subpart of part.parts) {
          if (subpart.mimeType === 'text/html' && subpart.body?.data) {
            html = Buffer.from(subpart.body.data, 'base64url').toString('utf-8');
            break;
          }
        }
      }
    }
  }
  // 4. Raw format - single body
  else if (data.payload?.body?.data) {
    html = Buffer.from(data.payload.body.data, 'base64url').toString('utf-8');
  }

  const subject = data.subject || data.Subject || 'Sans sujet';
  const from = data.from?.value?.[0]?.address || data.From || data.from || 'unknown';

  if (!html) {
    results.push({
      json: {
        newsletter_name: subject,
        from: from,
        received_at: new Date().toISOString(),
        links: [],
        link_count: 0,
        _debug: 'No HTML body found. Available keys: ' + Object.keys(data).join(', ')
      }
    });
    continue;
  }

  const linkRegex = /href=["'](https?:\/\/[^"'\s>]+)["']/gi;
  const seen = new Set();
  const links = [];
  let match;

  while ((match = linkRegex.exec(html)) !== null) {
    let url = match[1];
    url = url.replace(/&amp;/g, '&');

    const tldnMatch = url.match(/tldrnewsletter\.com\/CL0\/(https?[^/]+)/);
    if (tldnMatch) {
      try { url = decodeURIComponent(tldnMatch[1]); } catch (e) {}
    }

    if (seen.has(url)) continue;
    seen.add(url);

    const skip = [
      'unsubscribe', 'list-manage', 'mailchimp', 'tracking.tldrnewsletter',
      'tldrnewsletter.com/CL0',
      'click.', 'mailto:', 'tel:', '.png', '.jpg', '.gif', '.svg',
      'facebook.com', 'twitter.com', 'x.com/share', 'linkedin.com/share',
      'linkedin.com/feed', 'linkedin.com/in/',
      'instagram.com', 'youtube.com/channel', 'open.spotify.com',
      'play.google.com', 'apps.apple.com', 'beacon', 'pixel',
      'doubleclick', 'analytics',
      'campaign-archive', 'manage-preferences', 'view-in-browser',
      'email.mg.', 'sendgrid.net', 'substack.com/subscribe',
      'convertkit', 'beehiiv.com/subscribe',
      'refer.tldr.tech', 'hub.sparklp.co', 'a.tldrnewsletter.com',
      'tldr.tech/ai?utm', 'advertise.tldr.tech', 'jobs.ashbyhq.com',
      'tldr.tech/ai/manage', 'go.clerk.com',
      'webinars.atlassian.com'
    ];

    const urlLower = url.toLowerCase();
    if (skip.some(s => urlLower.includes(s))) continue;
    if (url.length < 20) continue;

    let title = '';
    try {
      const escapedUrl = url.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const titleRegex = new RegExp('href=["\'][^"\']* ' + escapedUrl.slice(0, 40) + '[^"\']*["\'][^>]*>([^<]+)<', 'i');
      const titleMatch = html.match(titleRegex);
      if (titleMatch && titleMatch[1]) {
        title = titleMatch[1].trim();
      }
    } catch (e) {}

    links.push({ url, title });
  }

  results.push({
    json: {
      newsletter_name: subject,
      from: from,
      received_at: new Date().toISOString(),
      links: links,
      link_count: links.length
    }
  });
}

return results;

// Flatten links for individual scraping
const items = $input.all();
const allLinks = [];

for (const item of items) {
  const newsletter = item.json.newsletter_name;
  const from = item.json.from;
  const receivedAt = item.json.received_at;
  const links = item.json.links || [];

  for (const link of links) {
    allLinks.push({
      json: {
        url: link.url,
        title: link.title,
        newsletter_name: newsletter,
        from: from,
        received_at: receivedAt
      }
    });
  }
}

return allLinks;

// Merge scraped content back with metadata
const item = $input.first();
const batchItem = $('Loop Over Links').first();

return [{
  json: {
    url: batchItem.json.url,
    title: batchItem.json.title,
    newsletter_name: batchItem.json.newsletter_name,
    from: batchItem.json.from,
    received_at: batchItem.json.received_at,
    content: item.json.data || item.json.body || '',
    scraped: !item.json.error
  }
}];

// Aggregate all scraped articles and prepare as binary for file writing
// Files are written to /data/veilleur/raw/ with date-prefixed names
// Filename uses sender domain + HHmm timestamp to avoid collisions
// when multiple newsletters arrive on the same day.
const items = $input.all();
const date = new Date().toISOString().split('T')[0];

function senderDomain(email) {
  const match = (email || '').match(/@([^>\s]+)/);
  if (!match) return 'unknown';
  return match[1]
    .toLowerCase()
    .replace(/^(mail|email|newsletter|news|hello|info|noreply|no-reply)\./, '')
    .replace(/\.[a-z]{2,4}$/, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function timeSlug(isoDate) {
  const d = new Date(isoDate);
  return String(d.getUTCHours()).padStart(2, '0') + String(d.getUTCMinutes()).padStart(2, '0');
}

const byNewsletter = {};
for (const item of items) {
  const key = item.json.newsletter_name || 'unknown';
  if (!byNewsletter[key]) {
    byNewsletter[key] = {
      newsletter: key,
      from: item.json.from,
      received_at: item.json.received_at,
      links: []
    };
  }
  byNewsletter[key].links.push({
    url: item.json.url,
    title: item.json.title,
    content: item.json.content || '',
    scraped: item.json.scraped
  });
}

const results = [];
for (const [name, data] of Object.entries(byNewsletter)) {
  const domain = senderDomain(data.from);
  const time = timeSlug(data.received_at);
  const filename = `${date}-newsletter-${domain}-${time}.json`;
  const content = JSON.stringify(data, null, 2);
  const binaryData = await this.helpers.prepareBinaryData(
    Buffer.from(content, 'utf-8'),
    filename,
    'application/json'
  );

  results.push({
    json: {
      date: date,
      filename: filename,
      filepath: `/data/veilleur/raw/${filename}`,
      newsletter: name,
      link_count: data.links.length
    },
    binary: {
      data: binaryData
    }
  });
}

return results;
